set -u; D=~/.cache/g250-dav; rm -rf "$D"; mkdir -p "$D/cfg"; cd "$D"
echo '' | base64 -d | gunzip > responder.py
python3 responder.py "$D/capture.jsonl" "$D/port" > "$D/responder.log" 2>&1 &
RP=$!
for i in $(seq 1 50); do [ -s "$D/port" ] && break; sleep 0.1; done
PORT=$(cat "$D/port"); U="http://127.0.0.1:$PORT/repo"
SVN="svn --non-interactive --no-auth-cache --config-dir $D/cfg --config-option servers:global:http-timeout=10"
run() { echo "## $*" | sed "s#$D#D#g"; "$@" > "$D/out.txt" 2>&1; echo "exit $?"; tail -1 "$D/out.txt" | sed "s#$D#D#g"; }
run $SVN blame "$U/trunk/f.txt"
run $SVN propset --revprop -r 5 svn:log "a new message" "$U"
run $SVN lock -m "editing it" "$U/trunk/f.txt"
run $SVN unlock --force "$U/trunk/f.txt"
kill $RP; wait $RP 2>/dev/null
echo "== CAPTURE"; python3 -c 'import json,sys; [print(json.dumps(r)) for r in map(json.loads, open(sys.argv[1])) if r["method"] in ("PROPPATCH","LOCK","UNLOCK") or (r["method"] == "REPORT" and "file-revs" in __import__("base64").b64decode(r["body"]).decode("utf-8","replace"))]' "$D/capture.jsonl"
cd ~ && rm -rf "$D"
